import { useCallback, useEffect, useMemo, useState } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import { io } from "socket.io-client";
import { CalendarDays, CheckCircle2, CircleDollarSign, Clock3, Plus, TicketCheck, Trophy } from "lucide-react";
import { Cell, Line, LineChart, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import EventVendorLayout from "./EventVendorLayout";
import ManageEvents from "./ManageEvents";
import EventBookings from "./EventBookings";
import EventCalendar from "./EventCalendar";
import EventRevenue from "./EventRevenue";
import EventNotes from "./EventNotes";
import { eventDate, eventMoney, eventRequest } from "../../services/eventApi";
import "./EventDashboard.css";

const colors=["#087f5b","#f0a23b","#df5b5b"];
export default function EventDashboard(){
 const navigate=useNavigate(),[params]=useSearchParams(),tab=params.get("tab")||"overview",[search,setSearch]=useState(""),[events,setEvents]=useState([]),[bookings,setBookings]=useState([]),[notes,setNotes]=useState([]),[notifications,setNotifications]=useState([]),[stats,setStats]=useState({}),[revenue,setRevenue]=useState({chart:[]}),[loading,setLoading]=useState(true),[error,setError]=useState("");
 const load=useCallback(async()=>{setLoading(true);setError("");try{const [eventRows,bookingRows,noteRows,statRows,revenueRows,alertRows]=await Promise.all([eventRequest("/vendor/events"),eventRequest("/vendor/events/bookings"),eventRequest("/vendor/events/notes"),eventRequest("/vendor/events/dashboard/stats"),eventRequest("/vendor/events/revenue?range=monthly"),eventRequest("/vendor/events/notifications")]);setEvents(eventRows);setBookings(bookingRows);setNotes(noteRows);setStats(statRows);setRevenue(revenueRows);setNotifications(alertRows)}catch(requestError){setError(requestError.response?.data?.message||requestError.message)}finally{setLoading(false)}},[]);
 useEffect(()=>{load()},[load]);
 useEffect(()=>{const token=localStorage.getItem("token")||sessionStorage.getItem("token"),socket=io("http://localhost:5000",{auth:{token},transports:["websocket","polling"]});socket.on("eventDashboardUpdated",load);return()=>socket.disconnect()},[load]);
 const content=tab==="manage"?<ManageEvents events={events} search={search} reload={load}/>:tab==="bookings"?<EventBookings bookings={bookings} search={search} reload={load}/>:tab==="calendar"?<EventCalendar/>:tab==="revenue"?<EventRevenue initial={revenue}/>:tab==="notes"?<EventNotes notes={notes} events={events} reload={load}/>:<Overview {...{events,bookings,notes,notifications,stats,revenue,loading,error,navigate}}/>;
 return <EventVendorLayout search={search} setSearch={setSearch}>{content}</EventVendorLayout>;
}

function Overview({events,bookings,notes,notifications,stats,revenue,loading,error,navigate}){
 const status=useMemo(()=>[{name:"Confirmed",value:bookings.filter(row=>row.booking_status==="confirmed").length},{name:"Pending",value:bookings.filter(row=>row.booking_status==="pending").length},{name:"Cancelled",value:bookings.filter(row=>row.booking_status==="cancelled").length}],[bookings]);
 const cards=[["Total Events",stats.total_events,CalendarDays],["Active Events",stats.active_events,CheckCircle2],["Upcoming Events",stats.upcoming_events,Clock3],["Completed Events",stats.completed_events,Trophy],["Total Bookings",stats.total_bookings,TicketCheck],["Total Revenue",eventMoney(stats.total_revenue),CircleDollarSign],["Pending Settlement",eventMoney(stats.pending_settlement),Clock3]];
 const hero=<section className="ed-welcome"><div><small>EVENT VENDOR PANEL</small><h1>Event Dashboard</h1><p>Manage events, bookings, revenue, calendar and team activity.</p></div><button onClick={()=>navigate("/vendor/event/add")}><Plus/> Add Event</button></section>;
 if(loading)return <>{hero}<DashboardSkeleton/></>;
 return <>{hero}{error&&<div className="ed-alert">{error}</div>}<section className="ed-kpis">{cards.map(([label,value,Icon])=><article key={label}><span><Icon/></span><div><small>{label}</small><h2>{value||0}</h2></div></article>)}</section><section className="ed-grid"><RevenueChart revenue={revenue}/><StatusChart status={status}/></section><section className="ed-grid"><MiniCalendar events={events}/><UpcomingEvents events={events}/></section><section className="ed-grid"><Notes notes={notes} navigate={navigate}/><RecentNotifications notifications={notifications}/></section><RecentBookings bookings={bookings} navigate={navigate}/></>;
}
function RevenueChart({revenue}){return <article className="ed-panel"><header><div><small>LIVE PERFORMANCE</small><h3>Revenue overview</h3></div><b>Last 30 days</b></header><div className="ed-chart"><ResponsiveContainer><LineChart data={revenue.chart||[]}><XAxis dataKey="label" axisLine={false} tickLine={false}/><YAxis hide/><Tooltip formatter={value=>eventMoney(value)}/><Line type="monotone" dataKey="revenue" stroke="#087f5b" strokeWidth={3} dot={{r:3}}/></LineChart></ResponsiveContainer></div>{!revenue.chart?.length&&<Empty text="Revenue will chart after your first successful booking."/>}</article>}
function StatusChart({status}){const total=status.reduce((sum,item)=>sum+item.value,0);return <article className="ed-panel"><header><h3>Booking status</h3></header>{total?<div className="ed-pie"><ResponsiveContainer><PieChart><Pie data={status} dataKey="value" innerRadius={50} outerRadius={76}>{status.map((item,index)=><Cell key={item.name} fill={colors[index]}/>)}</Pie><Tooltip/></PieChart></ResponsiveContainer><div>{status.map((item,index)=><p key={item.name}><i style={{background:colors[index]}}/>{item.name}<b>{item.value}</b></p>)}</div></div>:<Empty text="Booking status insights will appear here."/>}</article>}
function MiniCalendar({events}){const now=new Date(),days=new Date(now.getFullYear(),now.getMonth()+1,0).getDate(),first=new Date(now.getFullYear(),now.getMonth(),1).getDay();return <article className="ed-panel"><header><div><small>LIVE CALENDAR</small><h3>{now.toLocaleDateString("en-IN",{month:"long",year:"numeric"})}</h3></div></header><div className="ed-mini-calendar">{"SMTWTFS".split("").map((label,index)=><b key={index}>{label}</b>)}{Array.from({length:first},(_,index)=><i key={index}/>)}{Array.from({length:days},(_,index)=>index+1).map(day=>{const count=events.filter(event=>{const value=new Date(`${String(event.event_date).slice(0,10)}T00:00:00`);return value.getMonth()===now.getMonth()&&value.getDate()===day}).length;return <span className={count?"has-event":""} key={day}>{day}{count>0&&<em>{count}</em>}</span>})}</div></article>}
function UpcomingEvents({events}){const today=new Date().toISOString().slice(0,10),rows=events.filter(event=>event.status==="active"&&String(event.event_date).slice(0,10)>=today).sort((a,b)=>String(a.event_date).localeCompare(String(b.event_date))).slice(0,5);return <article className="ed-panel"><header><div><small>NEXT ON YOUR SCHEDULE</small><h3>Upcoming events</h3></div></header><div className="ed-upcoming">{rows.map(event=><div key={event.id}><time><b>{new Date(`${String(event.event_date).slice(0,10)}T00:00:00`).getDate()}</b>{new Date(`${String(event.event_date).slice(0,10)}T00:00:00`).toLocaleDateString("en-IN",{month:"short"})}</time><span><b>{event.event_name}</b><small>{event.venue_name}, {event.city} · {String(event.start_time).slice(0,5)}</small></span><em>{event.available_tickets} left</em></div>)}{!rows.length&&<Empty text="No upcoming events. Publish one to build your schedule."/>}</div></article>}
function Notes({notes,navigate}){return <article className="ed-panel"><header><h3>Notes</h3><button onClick={()=>navigate("/vendor/events?tab=notes")}>View all</button></header><div className="ed-notes">{notes.slice(0,4).map(note=><div key={note.id} className={note.priority}><b>{note.note_title}</b><small>{note.event_name||"General"} · {note.status.replace("_"," ")}</small><p>{note.note_description}</p></div>)}{!notes.length&&<Empty text="No notes yet. Add operational reminders for your team."/>}</div></article>}
function RecentNotifications({notifications}){return <article className="ed-panel"><header><div><small>ACTIVITY CENTER</small><h3>Recent notifications</h3></div></header><div className="ed-notifications">{notifications.slice(0,5).map(item=><div key={item.id}><i className={item.is_read?"read":""}/><span><b>{item.title}</b><p>{item.message}</p></span><small>{eventDate(item.created_at)}</small></div>)}{!notifications.length&&<Empty text="You’re all caught up. New activity will appear here."/>}</div></article>}
function RecentBookings({bookings,navigate}){return <article className="ed-panel"><header><h3>Recent bookings</h3><button onClick={()=>navigate("/vendor/events?tab=bookings")}>View all</button></header><div className="ed-table-wrap"><table><thead><tr><th>Booking ID</th><th>Customer</th><th>Event</th><th>Tickets</th><th>Amount</th><th>Status</th><th>Date</th></tr></thead><tbody>{bookings.slice(0,6).map(booking=><tr key={booking.id}><td>{booking.id}</td><td>{booking.customer_name}</td><td>{booking.event_name}</td><td>{booking.quantity}</td><td>{eventMoney(booking.total_amount)}</td><td><span className={`ed-status ${booking.booking_status}`}>{booking.booking_status}</span></td><td>{eventDate(booking.created_at)}</td></tr>)}</tbody></table>{!bookings.length&&<Empty text="Bookings will appear after customers purchase tickets."/>}</div></article>}
function DashboardSkeleton(){return <><section className="ed-kpis ed-skeleton">{Array.from({length:7},(_,index)=><article key={index}><i/><div><i/><i/></div></article>)}</section><section className="ed-grid ed-skeleton"><article/><article/></section><section className="ed-panel ed-skeleton-table"><i/><i/><i/><i/></section></>}
function Empty({text}){return <div className="ed-empty">{text}</div>}
